<script lang="ts">
  import { t, caption, locale, type Message } from '../i18n';
  import { liveValue } from './live-value';
  export interface Model {
    paper: string; paperName: string; widthCm: number; heightCm: number; width: number; height: number; rawWidthCm: number; rawHeightCm: number; orient: string;
    mt: number; ml: number; current: number; papers: { key: string; name: string | Message }[];
    pages: { objects: number; thumbnail: string }[];
  }
  let { model }: { model: Model } = $props();
  const icons = { up: '<path d="M10 15V5M6 9l4-4 4 4"/>', down: '<path d="M10 5v10M6 11l4 4 4-4"/>', dup: '<path d="M7 7h9v9H7z"/><path d="M4 13V4h9"/>', ins: '<path d="M10 5v10M5 10h10"/>', del: '<path d="M4 5.5h12M8 5.5V3.5h4v2M5.5 5.5l1 12h7l1-12"/>' };
  const round = (n: number) => +n.toFixed(2);
</script>
{#snippet number(key: string, value: number)}<input type="number" data-pp={key} {@attach liveValue(round(value))} step="0.25" min="0">{/snippet}
<h3>{t("page.heading", "Page", {}, $locale)} <small>{t("page.sizeSummary", "{paper} · {w} × {h} cm", { paper: model.paperName, w: round(model.widthCm), h: round(model.heightCm) }, $locale)}</small></h3><div class="sec">
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.paper", "Paper", {}, $locale)}</label><div class="ctl"><select data-pp="paper" {@attach liveValue(model.paper)}>{#each model.papers as paper}<option value={paper.key}>{caption(paper.name, $locale)}</option>{/each}</select></div></div>
  {#if model.paper === 'custom'}<div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.size.cm", "Size (cm)", {}, $locale)}</label><div class="ctl">{@render number('w', model.rawWidthCm)}<span class="x">×</span>{@render number('h', model.rawHeightCm)}</div></div>{/if}
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.orientation", "Orientation", {}, $locale)}</label><div class="ctl seg-ctl"><button data-ppo="portrait" class={model.orient !== 'landscape' ? 'on' : ''} title={t("ui.portrait", "Portrait", {}, $locale)}><svg viewBox="0 0 20 20"><path d="M6 3h8v14H6z"/></svg></button><button data-ppo="landscape" class={model.orient === 'landscape' ? 'on' : ''} title={t("ui.landscape", "Landscape", {}, $locale)}><svg viewBox="0 0 20 20"><path d="M3 6h14v8H3z"/></svg></button></div></div>
  <div class="row"><!-- svelte-ignore a11y_label_has_associated_control (Existing compound control caption.) --><label>{t("ui.margins", "Margins", {}, $locale)}</label><div class="ctl">{@render number('mt', model.mt)}{@render number('ml', model.ml)}</div></div><div class="hint-line">{t("ui.margins.top.bottom.left.right.cm.are.guides.only.snap.to.them.or.place.things.ri", "Margins (top/bottom · left/right, cm) are guides only: snap to them, or place things right to the edge. Shared with the Document view's page setup.", {}, $locale)}</div></div>
<h3>{t("pages.heading", "Pages", {}, $locale)} <small>{model.pages.length > 1 ? t('pages.count', '{n} pages', { n: model.pages.length }, $locale) : t('pages.count1', '{n} page', { n: model.pages.length }, $locale)} · PgUp / PgDn</small></h3><div class="sec pg-list">{#each model.pages as page, k}<div class={'pg-item' + (k === model.current ? ' on' : '')} data-pg="go" data-k={k} title={t('pages.goTo', 'Go to page {n}', { n: k + 1 }, $locale)}><div class="pg-thumb" style={'aspect-ratio:' + model.width + '/' + model.height}>{@html page.thumbnail}</div><div class="pg-meta"><b>{t("pages.number", "Page {n}", { n: k + 1 }, $locale)}</b><span>{page.objects > 1 ? t('pages.objects', '{n} objects', { n: page.objects }, $locale) : page.objects ? t('pages.object1', '1 object', {}, $locale) : t('pages.empty', 'empty', {}, $locale)}</span><div class="pg-acts">{#each [{ key: 'up', at: k, title: t('pages.up', 'Move page up', {}, $locale), disabled: k === 0 }, { key: 'down', at: k, title: t('pages.down', 'Move page down', {}, $locale), disabled: k === model.pages.length - 1 }, { key: 'ins', at: k + 1, title: t('pages.insert', 'Insert a blank page after this one', {}, $locale), disabled: model.pages.length >= 50 }, { key: 'dup', at: k, title: t('pages.duplicate', 'Duplicate this page', {}, $locale), disabled: model.pages.length >= 50 }, { key: 'del', at: k, title: t('pages.delete', 'Delete this page', {}, $locale), disabled: model.pages.length < 2 }] as action}<button class="icon" data-pg={action.key} data-k={action.at} title={action.title} disabled={action.disabled}><svg viewBox="0 0 20 20">{@html icons[action.key as keyof typeof icons]}</svg></button>{/each}</div></div></div>{/each}<button class="pg-add" data-pg="add" data-k={model.pages.length} title={t("ui.add.a.page.at.the.end", "Add a page at the end", {}, $locale)} disabled={model.pages.length >= 50}>{t("ui.add.page", "+ Add page", {}, $locale)}</button></div>
